import React, { useState } from "react";
import { useApp } from "../../context/AppContext";

export default function KamyoncuProfil() {
  const { oturum, cikisYap } = useApp();
  const [belgeEklendi, setBelgeEklendi] = useState(false);

  const belgeler = [
    { id: 1, ad: "Ehliyet (E Sınıfı)", ok: true, tarih: "2018-03-15" },
    { id: 2, ad: "Araç Ruhsatı", ok: true, tarih: "2019-07-20" },
    { id: 3, ad: "Sorumluluk Sigortası", ok: true, tarih: "2024-01-10" },
    { id: 4, ad: "SRC Belgesi", ok: false, tarih: "-" },
    { id: 5, ad: "ADR Belgesi", ok: false, tarih: "-" },
  ];

  const statler = [
    { val: "127", lbl: "Sefer" },
    { val: "98%", lbl: "Başarı" },
    { val: "4 Yıl", lbl: "Deneyim" },
    { val: "274", lbl: "KM" },
    { val: "4.9", lbl: "Puan" },
  ];

  const dosyaInputRef = React.createRef();

  const belgeEkle = () => {
    if (dosyaInputRef.current?.value) {
      setBelgeEklendi(true);
      setTimeout(() => setBelgeEklendi(false), 2000);
    }
  };

  return (
    <div className="scroll-content">
      {/* Profil Kartı */}
      <div className="card" style={{ textAlign: "center", padding: 24, marginBottom: 12 }}>
        <div style={{ fontSize: 52, marginBottom: 10 }}>🚛</div>
        <div className="display" style={{ fontSize: 28, color: "var(--sari)" }}>{oturum?.ad || "Mehmet Yılmaz"}</div>
        <div className="rating" style={{ marginTop: 6 }}>⭐ 4.9 — Güvenilir Sürücü</div>
        <div style={{ marginTop: 14 }}><span className="plaka">34 TYK 421</span></div>
        <div style={{ marginTop: 6, fontSize: 12, color: "var(--text3)" }}>TIR / Kapalı Kasa • İstanbul</div>

        {/* İstatistikler */}
        <div className="stat-grid" style={{ marginTop: 16 }}>
          {statler.map((s, i) => (
            <div key={i} className="stat-box">
              <div className="stat-val">{s.val}</div>
              <div className="stat-lbl">{s.lbl}</div>
            </div>
          ))}
        </div>
      </div>

      {/* Abonelik */}
      <div className="card" style={{ marginBottom: 12, background: "rgba(245,166,35,0.06)", borderColor: "rgba(245,166,35,0.3)" }}>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
          <div>
            <div style={{ fontWeight: 600, fontSize: 14 }}>⭐ Pro Üye</div>
            <div style={{ fontSize: 12, color: "var(--text3)", marginTop: 2 }}>Sınırsız teklif • Öncelikli görünüm</div>
          </div>
          <div style={{ textAlign: "right" }}>
            <div style={{ fontFamily: "var(--font-d)", fontSize: 20, color: "var(--sari)" }}>₺299/ay</div>
            <div style={{ fontSize: 11, color: "var(--yesil)" }}>Aktif</div>
          </div>
        </div>
      </div>

      {/* Belgeler */}
      <div className="card" style={{ marginBottom: 12 }}>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 12 }}>
          <div className="label">📁 Belgelerim</div>
          {belgeEklendi && (
            <div style={{ fontSize: 12, color: "var(--yesil)", animation: "fadeIn 0.3s" }}>✅ Eklendi!</div>
          )}
        </div>

        {belgeler.map((b) => (
          <div key={b.id} style={{
            background: "var(--bg2)",
            borderRadius: "var(--r)",
            padding: "12px 14px",
            marginBottom: 8,
            display: "flex",
            alignItems: "center",
            justifyContent: "space-between"
          }}>
            <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
              {b.ok ? (
                <span style={{ color: "var(--yesil)", fontSize: 20 }}>✓</span>
              ) : (
                <span style={{ color: "var(--text3)", fontSize: 20 }}>○</span>
              )}
              <div>
                <div style={{ fontSize: 14 }}>{b.ad}</div>
                {b.tarih !== "-" && <div style={{ fontSize: 11, color: "var(--text3)", marginTop: 2 }}>{b.tarih}</div>}
              </div>
            </div>
            <div style={{ fontSize: 11, color: "var(--text3)" }}> {b.tarih}</div>
          </div>
        ))}

        <div style={{ display: "flex", gap: 8 }}>
          <input
            ref={dosyaInputRef}
            type="file"
            id={`belge-input`}
            accept="image/*,.pdf"
            style={{ display: "none" }}
          />
          <label htmlFor={`belge-input`} style={{ flex: 1 }}>
            <button className="btn btn-secondary" style={{ width: "100%", fontSize: 13, padding: "12px" }}>
              + Belge Ekle
            </button>
          </label>
        </div>
      </div>

      {/* Menü */}
      <div className="card" style={{ marginBottom: 8 }}>
        {[
          { icon: "💳", text: "Banka Hesabım", color: "var(--mavi)" },
          { icon: "🔔", text: "Bildirim Ayarları", color: "var(--sari)" },
          { icon: "❓", text: "Yardım & Destek", color: "var(--text3)" },
          { icon: "🔒", text: "Gizlilik Politikası", color: "var(--text3)" },
          { icon: "⚙️", text: "Ayarlar", color: "var(--text3)" },
        ].map((item, i) => (
          <div key={i} style={{
            display: "flex",
            alignItems: "center",
            gap: 12,
            padding: "14px",
            borderBottom: i < 4 ? "1px solid var(--border)" : "none",
            cursor: "pointer",
            transition: "background 0.2s",
            borderRadius: i === 0 ? "var(--r)  var(--r) 0 0" : i === 4 ? "0 0 var(--r) var(--r)" : "0"
          }}
          styleHover={{
            background: "var(--bg2)"
          }}>
            <span style={{ fontSize: 20, width: 32 }}>{item.icon}</span>
            <span style={{ fontSize: 14, flex: 1 }}>{item.text}</span>
            <span style={{ color: "var(--text3)" }}>›</span>
          </div>
        ))}
      </div>

      {/* Çıkış Butonu */}
      <button onClick={cikisYap} className="btn btn-danger btn-full" style={{ marginTop: 8, padding: "14px" }}>
        🚪 Çıkış Yap
      </button>
    </div>
  );
}
